SELECT e.id, e.project_id, e.author_user_id,
       COALESCE(u.name, u.username) AS author_name,
       e.l1_summary, e.l2_detail, e.confidence, e.status, e.content_type, e.created_at
FROM memory_project_entries e
LEFT JOIN users u ON u.id = e.author_user_id
WHERE e.deleted = 0 AND e.project_id = #{projectId}
 AND e.status = #{status} 
 AND e.author_user_id = #{authorUserId} 
ORDER BY e.created_at DESC
LIMIT 200

SELECT e.id, e.project_id, e.author_user_id, COALESCE(u.name, u.username) AS author_name, e.l1_summary, e.l2_detail, e.confidence, e.status, e.content_type, e.direction, e.file_id, e.created_at, e.tag_ids, p.name AS project_name FROM memory_project_entries e LEFT JOIN users u ON u.id = e.author_user_id LEFT JOIN projects p ON p.id = e.project_id WHERE e.deleted = 0 AND e.status = 'ACTIVE' AND e.project_id IN
#{pid}
ORDER BY e.created_at DESC LIMIT 200

SELECT COUNT(*) FROM memory_project_entries e
WHERE e.deleted = 0 AND e.status = 'ACTIVE'
  AND e.project_id IN

      #{pid}

  AND NOT EXISTS (
      SELECT 1 FROM memory_entry_coverage c
      WHERE c.entry_id = e.id AND c.project_id = #{scopeProjectId}

          AND c.user_id = #{userId}
          AND c.user_id IS NULL

  )

